"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useDigitRoll } from "@/lib/0nlytype/use-digit-roll"
import { Button } from "@/components/ui/button"
import { Ring } from "@/components/ui/radial-chart"

type TimerState = "idle" | "running" | "paused" | "done"

type TimerProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** How long a session lasts, in seconds. Changing it resets the timer. */
  duration?: number
  /** Seconds already spent when it first shows, for a session picked up again. */
  defaultElapsed?: number
  /** What the time is for, e.g. "Writing". It also names the timer for assistive tech. */
  label?: React.ReactNode
  /** ring: a full ring round the time, emptying clockwise. horizon: a half ring on a horizon, the dot crossing it like the sun. */
  variant?: "ring" | "horizon"
  /** Called once when the time runs out. */
  onComplete?: () => void
  /** Pins a state for documentation: "running", "paused" or "done". It does not count. */
  "data-force"?: string
}

const still = () => typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches
const pad = (n: number) => String(n).padStart(2, "0")
const clock = (s: number) => {
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  return h ? `${h}:${pad(m)}:${pad(s % 60)}` : `${pad(m)}:${pad(s % 60)}`
}
const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`
const spoken = (s: number) => {
  const [h, m, sec] = [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60]
  return [h && plural(h, "hour"), m && plural(m, "minute"), sec && plural(sec, "second")].filter(Boolean).join(" ") || "0 seconds"
}
// Worth saying: every five minutes, each of the last five, and thirty seconds. Crossed, not hit, so a tab that slept still says it.
const mark = (m: number) => (m % 60 === 0 && (m % 300 === 0 || m <= 300)) || m === 30
const passed = (from: number, to: number) => {
  for (let m = to; m < from; m++) if (mark(m)) return true
  return false
}
const at = new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" })

/** The figures turn over like a counter's wheels, only those that changed, the units first. */
function Figures({ text }: { text: string }) {
  const { shown: valueShown, figs } = useDigitRoll(text, { order: text, distance: "0.4em" })
  const shown = String(valueShown)
  return (
    <span className="db-timer-figures" dir="ltr" aria-hidden="true">
      {[...shown].map((f, k) => (
        <span key={shown.length - k} ref={(el) => void (figs.current[k] = el)} data-colon={f === ":" || undefined}>
          {f}
        </span>
      ))}
    </span>
  )
}

/**
 * A countdown the person starts. The time is set large in tabular figures inside a hairline ring; the ring empties
 * clockwise from the top as the time goes, the accent dot leading it like a clock's hand. It only counts after
 * Start, follows the wall clock (so a hidden tab doesn't fall behind), and tells screen readers the time politely:
 * on each press, every five minutes, each of the last five, at thirty seconds, and when it's up.
 */
function Timer({ duration = 1500, defaultElapsed = 0, label, variant = "ring", onComplete, className, style, ...props }: TimerProps) {
  const total = Math.max(1, Math.round(duration))
  const force = ["running", "paused", "done"].find((s) => props["data-force"]?.split(" ").includes(s)) as TimerState | undefined
  const [left, setLeft] = React.useState(() => Math.min(total, Math.max(0, total - Math.round(defaultElapsed))))
  const [state, setState] = React.useState<TimerState>(left === 0 ? "done" : left < total ? "paused" : "idle")
  const [ends, setEnds] = React.useState<number | null>(null)
  const [said, setSaid] = React.useState("")
  const ring = React.useRef<HTMLSpanElement>(null)
  const done = React.useRef(onComplete)
  const was = React.useRef(total)
  React.useEffect(() => void (done.current = onComplete), [onComplete])

  // A new length starts over.
  React.useEffect(() => {
    if (was.current === total) return
    was.current = total
    setLeft(total)
    setState("idle")
    setEnds(null)
  }, [total])

  // Before paint, so the ring is never seen empty between a render and the first frame.
  React.useLayoutEffect(() => {
    if (state !== "running" || ends == null) return
    let frame = 0
    let prev = -1
    const smooth = !still()
    // The ring follows the clock every frame (under reduced motion, once a second); it is written here, not by React.
    const draw = (p: number) => {
      ring.current?.style.setProperty("--db-ring-p", String(p))
      ring.current?.style.setProperty("--db-ring-from", String(1 - p))
    }
    const tick = () => {
      const s = Math.max(0, Math.ceil((ends - Date.now()) / 1000))
      if (s === prev) return
      const was = prev
      prev = s
      setLeft(s)
      if (!smooth) draw(s / total)
      if (s === 0) {
        setState("done")
        setEnds(null)
        setSaid("Time is up.")
        done.current?.()
      } else if (was > 0 && passed(was, s)) setSaid(`${spoken(s)} left.`) // the press already said the first
    }
    const run = () => {
      draw(Math.max(0, ends - Date.now()) / 1000 / total)
      frame = requestAnimationFrame(run)
    }
    const beat = setInterval(tick, 250)
    document.addEventListener("visibilitychange", tick)
    tick()
    if (smooth) run()
    return () => {
      clearInterval(beat)
      cancelAnimationFrame(frame)
      document.removeEventListener("visibilitychange", tick)
    }
  }, [state, ends, total])

  const shown = force === "done" ? 0 : left
  const now = force ?? state
  function go() {
    if (state === "running") {
      const s = ends == null ? left : Math.max(0, Math.ceil((ends - Date.now()) / 1000))
      setLeft(s)
      setEnds(null)
      setState("paused")
      setSaid(`Paused, ${spoken(s)} left.`)
      return
    }
    const s = state === "done" ? total : left
    setLeft(s)
    setEnds(Date.now() + s * 1000)
    setState("running")
    setSaid(`${state === "paused" ? "Resumed" : "Started"}, ${spoken(s)} left.`)
  }
  function reset() {
    setLeft(total)
    setEnds(null)
    setState("idle")
    setSaid(`Reset to ${spoken(total)}.`)
  }

  const p = shown / total
  // Running, the effect draws the arc from the clock, so React lets go of it rather than set it back a second.
  const drawn = state === "running" && !force
  const note = now === "running" ? (ends ? `Ends ${at.format(ends)}` : "Running") : now === "paused" ? "Paused" : now === "done" ? "Done" : spoken(total)
  const named = typeof label === "string" ? `${label} timer` : "Timer"
  return (
    <div
      role="group"
      aria-label={named}
      data-slot="timer"
      data-variant={variant}
      data-state={now}
      className={cn("db-timer", className)}
      style={{ "--db-timer-chars": clock(total).length, ...style } as React.CSSProperties}
      {...props}
    >
      <div data-slot="timer-face" className="db-timer-face" aria-hidden="true">
        <Ring ref={ring} value={p} from={1 - p} head="start" style={drawn ? ({ "--db-ring-p": undefined, "--db-ring-from": undefined } as React.CSSProperties) : undefined} />
      </div>
      <div data-slot="timer-read" className="db-timer-read">
        <span role="timer" className="db-timer-time">
          <Figures text={clock(shown)} />
          <span className="db-sr">{spoken(shown)}</span>
        </span>
        <span className="db-timer-words">
          {label != null ? <span className="db-timer-label">{label}</span> : null}
          <span className="db-timer-note">{note}</span>
        </span>
      </div>
      <div data-slot="timer-actions" className="db-timer-actions">
        <Button variant="bracket" onClick={go}>
          {now === "running" ? "Pause" : now === "paused" ? "Resume" : now === "done" ? "Start again" : "Start"}
        </Button>
        <Button variant="bracket" onClick={reset} disabled={now === "idle"}>
          Reset
        </Button>
      </div>
      <p className="db-sr" aria-live="polite">
        {said}
      </p>
    </div>
  )
}

export { Timer, type TimerProps }

@layer components {
  /* ── db-timer ── a countdown the person starts: the time set large in tabular figures inside the calendar's hairline
     ring (db-ring, from radial-chart). The ring empties clockwise from the top as the time goes, the accent dot at its
     leading end like a clock's hand; the figures turn over like a counter's wheels. Done, a full stop lands. */
  .db-timer {
    display: grid; grid-template-columns: minmax(0, 1fr); inline-size: min(100%, var(--db-timer-size, 22rem)); justify-items: center; row-gap: var(--db-space-6); container-type: inline-size;
  }
  .db-timer-face { grid-area: 1 / 1; position: relative; inline-size: 100%; aspect-ratio: 1; }
  .db-timer .db-ring { --db-ring-head: var(--db-accent); }
  /* Running, the ring is drawn from the clock every frame, so it doesn't also ease; Reset still sweeps it back. */
  .db-timer[data-state="running"] .db-ring { transition: none; }

  .db-timer-read { grid-area: 1 / 1; place-self: center; display: grid; justify-items: center; row-gap: var(--db-space-3); text-align: center; }
  .db-timer-time {
    position: relative; font-size: clamp(var(--db-mf), calc(118cqi / var(--db-timer-chars, 5)), var(--db-fff)); line-height: 0.9; letter-spacing: var(--db-ff-tr); font-weight: 200;
    color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums; white-space: nowrap;
    transition: color var(--db-moderato) var(--db-exhale);
  }
  .db-timer-figures { position: relative; display: inline-flex; }
  .db-timer-figures > span { display: inline-block; }
  .db-timer-figures > [data-colon] { translate: 0 -0.06em; padding-inline: 0.02em; }
  /* The full stop is always there, unseen and out of the flow, so the time stays centred; done, it drops onto the line. */
  .db-timer-figures::after {
    content: "."; position: absolute; left: 100%; bottom: 0; opacity: 0; translate: 0 -0.4em;
    transition: opacity var(--db-allegro) var(--db-exhale), translate var(--db-moderato) var(--db-spiccato);
  }
  .db-timer[data-state="done"] .db-timer-figures::after { opacity: 1; translate: 0 0; transition-delay: var(--db-moderato); }
  /* Paused, the time is held in pencil until it goes on. */
  .db-timer[data-state="paused"] .db-timer-time { color: var(--db-pencil); }

  .db-timer-words { display: grid; justify-items: center; font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); }
  .db-timer-label { font-weight: 500; color: var(--db-ink); }
  .db-timer-note { color: var(--db-pencil); font-variant-numeric: tabular-nums; }

  /* The two presses stand either side of the centre line, so when Start becomes Pause or Start again, only it moves. */
  .db-timer-actions { display: grid; grid-template-columns: 1fr 1fr; inline-size: max-content; column-gap: var(--db-space-5); }
  .db-timer-actions > .db-btn:first-child { justify-self: end; }
  .db-timer-actions > .db-btn:last-child { justify-self: start; }

  /* horizon: the Eclipse. A half ring stands on a horizon that runs past it; the dot crosses it like the sun, from the
     start of the line to its end, and what's left of the arc is the day still to go. The time stands on the line and
     its words sit under it. Right to left, the sun crosses the other way. */
  .db-timer[data-variant="horizon"] { --db-ring-sweep: 0.5; --db-ring-start: -90deg; grid-template-rows: auto auto auto; row-gap: 0; padding-inline: var(--db-space-5); inline-size: min(100%, calc(var(--db-timer-size, 22rem) + 2 * var(--db-space-5))); }
  .db-timer[data-variant="horizon"] > .db-timer-face { aspect-ratio: 2; }
  .db-timer[data-variant="horizon"] .db-ring { inset-block-end: auto; aspect-ratio: 1; }
  .db-timer[data-variant="horizon"] > .db-timer-face::after { content: ""; position: absolute; inset-inline: calc(-1 * var(--db-space-5)); inset-block-end: 0; block-size: var(--db-hairline); background: var(--db-rule-strong); }
  .db-timer[data-variant="horizon"]:is([dir="rtl"], [dir="rtl"] *) > .db-timer-face { scale: -1 1; }
  .db-timer[data-variant="horizon"] > .db-timer-read { grid-row: 1 / span 2; place-self: stretch; grid-template-rows: subgrid; row-gap: 0; }
  .db-timer[data-variant="horizon"] .db-timer-time { align-self: end; font-size: clamp(var(--db-mf), calc(96cqi / var(--db-timer-chars, 5)), var(--db-fff)); line-height: 1; text-box: trim-end alphabetic; }
  .db-timer[data-variant="horizon"] .db-timer-words { padding-block-start: var(--db-space-3); }
  .db-timer[data-variant="horizon"] > .db-timer-actions { grid-row: 3; padding-block-start: var(--db-space-6); }
}
